import json
import os

SAVE_FILE = "savegame.json"


class Engine:
    """Runs a story graph: nodes, conditional choices, state effects, endings."""

    def __init__(self, story):
        self.story = story
        self.state = {
            "node": "start",
            "items": [],
            "flags": {},
            "stats": {"trust": 0, "coin": 5},
            "visited": [],
        }

    # -- conditional checks ------------------------------------------------
    def check(self, cond):
        if not cond:
            return True
        if "all" in cond:
            return all(self.check(c) for c in cond["all"])
        if "any" in cond:
            return any(self.check(c) for c in cond["any"])
        if "not" in cond:
            return not self.check(cond["not"])
        if "item" in cond:
            return cond["item"] in self.state["items"]
        if "no_item" in cond:
            return cond["no_item"] not in self.state["items"]
        if "flag" in cond:
            return bool(self.state["flags"].get(cond["flag"]))
        if "no_flag" in cond:
            return not self.state["flags"].get(cond["no_flag"])
        if "stat" in cond:
            name, op, val = cond["stat"]
            cur = self.state["stats"].get(name, 0)
            return {"<": cur < val, "<=": cur <= val, ">": cur > val,
                    ">=": cur >= val, "==": cur == val, "!=": cur != val}[op]
        return True

    # -- state effects -------------------------------------------------------
    def apply(self, effects):
        if not effects:
            return
        for it in effects.get("add_items", []):
            if it not in self.state["items"]:
                self.state["items"].append(it)
        for it in effects.get("remove_items", []):
            if it in self.state["items"]:
                self.state["items"].remove(it)
        self.state["flags"].update(effects.get("set_flags", {}))
        for k, v in effects.get("add_stats", {}).items():
            self.state["stats"][k] = self.state["stats"].get(k, 0) + v
        for k, v in effects.get("set_stats", {}).items():
            self.state["stats"][k] = v

    # -- node helpers --------------------------------------------------------
    def node(self):
        return self.story[self.state["node"]]

    def text(self):
        node = self.node()
        for variant in node.get("variants", []):
            if self.check(variant["if"]):
                return variant["text"]
        return node["text"]

    def choices(self):
        return [c for c in self.node().get("choices", []) if self.check(c.get("if"))]

    def is_ending(self):
        return self.node().get("ending", False)

    # -- save / load -----------------------------------------------------------
    def save(self):
        with open(SAVE_FILE, "w", encoding="utf-8") as f:
            json.dump(self.state, f)

    def load(self):
        if os.path.exists(SAVE_FILE):
            with open(SAVE_FILE, encoding="utf-8") as f:
                self.state = json.load(f)
            return True
        return False

    # -- main loop ---------------------------------------------------------------
    def run(self):
        print("=" * 60)
        print("THE EMBER GATE - an interactive story")
        print("=" * 60)
        while True:
            if self.state["node"] not in self.state["visited"]:
                self.state["visited"].append(self.state["node"])
            print("\n" + "-" * 60)
            print(self.text())
            if self.is_ending():
                self.show_end()
                return
            choices = self.choices()
            for i, c in enumerate(choices, 1):
                print(f"  {i}. {c['text']}")
            print("\nCommands: (s)ave  (l)oad  (q)uit")
            raw = input("> ").strip().lower()
            if raw in ("s", "save"):
                self.save()
                print("Saved.")
                continue
            if raw in ("l", "load"):
                print("Loaded." if self.load() else "No save found.")
                continue
            if raw in ("q", "quit"):
                print("Goodbye.")
                return
            if not raw.isdigit() or not (1 <= int(raw) <= len(choices)):
                print("Choose a valid option.")
                continue
            choice = choices[int(raw) - 1]
            self.apply(choice.get("effects"))
            self.state["node"] = choice["next"]

    def show_end(self):
        print("\n" + "=" * 60)
        print("*** " + self.node().get("title", "THE END") + " ***")
        print("Items:", ", ".join(self.state["items"]) or "none")
        print("Stats:", self.state["stats"])
        print("Flags:", ", ".join(k for k, v in self.state["flags"].items() if v) or "none")
        print("=" * 60)
